import pandas as pd

def _b(x):
    return 1.0 if bool(x) else 0.0

s = pd.Series(pd.arrays.SparseArray([0.0, np.nan]))
dense = pd.Series([0.0, np.nan])

probe("series_sparse_any_default", _b(s.any()))
probe("series_dense_any_default", _b(dense.any()))

try:
    probe("array_any_skipna_true", _b(pd.arrays.SparseArray([0.0, np.nan], fill_value=0.0).any(skipna=True)))
except TypeError:
    probe("array_any_skipna_true", np.nan)

try:
    probe("array_any_skipna_false", _b(pd.arrays.SparseArray([0.0, np.nan], fill_value=0.0).any(skipna=False)))
except TypeError:
    probe("array_any_skipna_false", np.nan)

